     2| * IVX Task Execution State Machine
     3| *
     4| * Owner mandate 2026-07-20 Phase 1: replace the simplified task status logic
     5| * with a real 17-state state machine that enforces legal transitions and the
     6| * owner's completion rules.
     7| *
     8| * Rules (enforced in canTransition + assertCanTransition):
     9| *   - DEPLOYED means only that a deployment occurred.
    10| *   - VERIFIED means the requested acceptance tests passed.
    11| *   - A task cannot become VERIFIED from /health alone.
    12| *   - A development task cannot become VERIFIED when no code changed unless the
    13| *     system proves that configuration, data, infrastructure, or an external
    14| *     dependency was the actual cause.
    15| *   - If no work was completed, status must be BLOCKED, FAILED, or
    16| *     NO_CHANGE_REQUIRED.
    17| *   - Never display "development completed" when the code diff is empty.
    18| *
    19| * This module is intentionally runtime-free and does NOT import worker types,
    20| * to avoid circular dependencies.
    21| */
    22|
    23|export const IVX_TASK_STATE_MACHINE_MARKER = 'ivx-task-state-machine-2026-07-21';
    24|
    25|export type IVXTaskState =
    26|  | 'RECEIVED'
    27|  | 'ANALYZING'
    28|  | 'REPRODUCING'
    29|  | 'ROOT_CAUSE_IDENTIFIED'
    30|  | 'IMPLEMENTING'
    31|  | 'CODE_CHANGED'
    32|  | 'TESTING'
    33|  | 'QA_REQUIRED'
    34|  | 'QA_IN_PROGRESS'
    35|  | 'READY_TO_DEPLOY'
    36|  | 'DEPLOYING'
    37|  | 'DEPLOYED'
    38|  | 'PRODUCTION_VERIFYING'
    39|  | 'VERIFIED'
    40|  | 'COMPLETED'
    41|  | 'BLOCKED'
    42|  | 'FAILED'
    43|  | 'NO_CHANGE_REQUIRED';
    44|
    45|export const ALL_TASK_STATES: readonly IVXTaskState[] = [
    46|  'RECEIVED',
    47|  'ANALYZING',
    48|  'REPRODUCING',
    49|  'ROOT_CAUSE_IDENTIFIED',
    50|  'IMPLEMENTING',
    51|  'CODE_CHANGED',
    52|  'TESTING',
    53|  'QA_REQUIRED',
    54|  'QA_IN_PROGRESS',
    55|  'READY_TO_DEPLOY',
    56|  'DEPLOYING',
    57|  'DEPLOYED',
    58|  'PRODUCTION_VERIFYING',
    59|  'VERIFIED',
    60|  'COMPLETED',
    61|  'BLOCKED',
    62|  'FAILED',
    63|  'NO_CHANGE_REQUIRED',
    64|] as const;
    65|
    66|export const TERMINAL_TASK_STATES: ReadonlySet<IVXTaskState> = new Set([
    67|  'VERIFIED',
    68|  'COMPLETED',
    69|  'BLOCKED',
    70|  'FAILED',
    71|  'NO_CHANGE_REQUIRED',
    72|]);
    73|
    74|/**
    75| * Task types that drive the terminal-state completion rules. The guard uses
    76| * these to decide which gates are required for COMPLETED vs VERIFIED.
    77| * Owner mandate 2026-07-21: a task must NEVER finish FAILED when its requested
    78| * gates all succeeded; deploy/feature-verification are only required when
    79| * deployment was explicitly requested.
    80| */
    81|export type IVXGuardTaskType =
    82|  | 'CODE_FIX'
    83|  | 'FEATURE'
    84|  | 'UI_FIX'
    85|  | 'DATA_FIX'
    86|  | 'CONFIGURATION_FIX'
    87|  | 'INFRASTRUCTURE_FIX'
    88|  | 'DEPLOYMENT'
    89|  | 'DEPLOY_ONLY'
    90|  | 'QA_ONLY'
    91|  | 'INVESTIGATION'
    92|  | 'CONTENT_REQUEST'
    93|  | 'BUSINESS_ANALYSIS'
    94|  | 'FACTORY';
    95|
    96|/**
    97| * Legal forward transitions. A task may not skip from RECEIVED straight to
    98| * DEPLOYED or VERIFIED — it must walk the senior-developer loop.
    99| */
   100|const LEGAL_TRANSITIONS: ReadonlyMap<IVXTaskState, ReadonlySet<IVXTaskState>> = new Map([
   101|  ['RECEIVED', new Set(['ANALYZING', 'COMPLETED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
   102|  ['ANALYZING', new Set(['REPRODUCING', 'ROOT_CAUSE_IDENTIFIED', 'COMPLETED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
   103|  ['REPRODUCING', new Set(['ROOT_CAUSE_IDENTIFIED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
   104|  ['ROOT_CAUSE_IDENTIFIED', new Set(['IMPLEMENTING', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
   105|  ['IMPLEMENTING', new Set(['CODE_CHANGED', 'BLOCKED', 'FAILED', 'NO_CHANGE_REQUIRED'])],
   106|  ['CODE_CHANGED', new Set(['TESTING', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   107|  ['TESTING', new Set(['QA_REQUIRED', 'READY_TO_DEPLOY', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   108|  ['QA_REQUIRED', new Set(['QA_IN_PROGRESS', 'BLOCKED', 'FAILED'])],
   109|  ['QA_IN_PROGRESS', new Set(['READY_TO_DEPLOY', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   110|  ['READY_TO_DEPLOY', new Set(['DEPLOYING', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   111|  ['DEPLOYING', new Set(['DEPLOYED', 'BLOCKED', 'FAILED'])],
   112|  ['DEPLOYED', new Set(['PRODUCTION_VERIFYING', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   113|  ['PRODUCTION_VERIFYING', new Set(['VERIFIED', 'COMPLETED', 'BLOCKED', 'FAILED'])],
   114|  ['VERIFIED', new Set()],
   115|  ['COMPLETED', new Set()],
   116|  ['BLOCKED', new Set()],
   117|  ['FAILED', new Set()],
   118|  ['NO_CHANGE_REQUIRED', new Set()],
   119|]);
   120|
   121|/**
   122| * Transition guard: verifies a transition is legal per the state machine.
   123| * Also enforces the owner's completion rules:
   124| *   - A development task cannot transition to VERIFIED with an empty diff
   125| *     unless an external cause is proven.
   126| *   - A task cannot transition to VERIFIED from /health alone (requires
   127| *     featureVerificationOk).
   128| *   - A task cannot transition to VERIFIED with no deployment for development
   129| *     tasks.
   130| */
   131|export type IVXTransitionGuardInput = {
   132|  from: IVXTaskState;
   133|  to: IVXTaskState;
   134|  isDevelopmentTask: boolean;
   135|  filesChangedCount: number;
   136|  testsRun: boolean;
   137|  testsPassed: boolean;
   138|  deployId: string | null;
   139|  productionHealthOk: boolean;
   140|  featureVerificationOk: boolean | null;
   141|  externalCauseProven: boolean;
   142|  /** Owner mandate 2026-07-21: whether deployment was explicitly requested.
   143|   *  When false, a CODE_CHANGE task may reach COMPLETED without deployId /
   144|   *  productionHealthOk / featureVerificationOk. Defaults to false (treat
   145|   *  missing as "deploy not requested") so legacy callers keep working. */
   146|  deployRequested?: boolean;
   147|  /** Whether a targeted typecheck was run and passed. Required for COMPLETED
   148|   *  on development tasks. Defaults to false. */
   149|  typecheckPassed?: boolean;
   150|  /** Whether the GitHub commit was created and verified (commitSha present).
   151|   *  Required for COMPLETED on development tasks and DEPLOY_ONLY. */
   152|  commitVerified?: boolean;
   153|  /** Task type used to decide which gates apply for COMPLETED. Falls back to
   154|   *  isDevelopmentTask for legacy callers. */
   155|  taskType?: IVXGuardTaskType;
   156|};
   157|
   158|export type IVXTransitionGuardResult = {
   159|  ok: boolean;
   160|  legal: boolean;
   161|  reasons: string[];
   162|  from: IVXTaskState;
   163|  to: IVXTaskState;
   164|};
   165|
   166|export function isTerminalTaskState(state: IVXTaskState): boolean {
   167|  return TERMINAL_TASK_STATES.has(state);
   168|}
   169|
   170|export function canTransition(from: IVXTaskState, to: IVXTaskState): boolean {
   171|  const allowed = LEGAL_TRANSITIONS.get(from);
   172|  return allowed ? allowed.has(to) : false;
   173|}
   174|
   175|export function assertCanTransition(input: IVXTransitionGuardInput): IVXTransitionGuardResult {
   176|  const reasons: string[] = [];
   177|  const { from, to } = input;
   178|
   179|  // Check structural legality first.
   180|  if (!canTransition(from, to)) {
   181|    reasons.push(`Illegal transition: ${from} -> ${to} is not a permitted forward transition.`);
   182|    return { ok: false, legal: false, reasons, from, to };
   183|  }
   184|
   185|  // Owner mandate 2026-07-21: COMPLETED is the honest success terminal for
   186|  // tasks that fulfilled all REQUESTED gates but did not deploy / run feature
   187|  // verification (e.g. "commit but do not deploy"). VERIFIED remains the
   188|  // success terminal only for the full deploy + production-verify path.
   189|  if (to === 'COMPLETED') {
   190|    const tt = input.taskType;
   191|    const isDev = input.isDevelopmentTask || tt === 'CODE_FIX' || tt === 'FEATURE' || tt === 'UI_FIX' || tt === 'DATA_FIX';
   192|    const isReadOnly = tt === 'INVESTIGATION';
   193|    const isQaOnly = tt === 'QA_ONLY';
   194|    const isDeployOnly = tt === 'DEPLOY_ONLY';
   195|
   196|    if (isDev) {
   197|      // CODE_CHANGE + NO_DEPLOY: PATCH + TESTS + TYPECHECK + COMMIT + GITHUB_VERIFY = COMPLETED
   198|      // CODE_CHANGE + DEPLOY: must go through VERIFIED, not COMPLETED.
   199|      if (input.deployRequested) {
   200|        reasons.push('A development task with deploy requested must reach VERIFIED via PRODUCTION_VERIFYING, not COMPLETED.');
   201|        return { ok: false, legal: true, reasons, from, to };
   202|      }
   203|      if (input.filesChangedCount === 0) {
   204|        reasons.push('A development task cannot become COMPLETED with an empty diff.');
   205|        return { ok: false, legal: true, reasons, from, to };
   206|      }
   207|      if (!input.testsRun) {
   208|        reasons.push('Files changed but tests were not run — cannot become COMPLETED.');
   209|        return { ok: false, legal: true, reasons, from, to };
   210|      }
   211|      if (!input.testsPassed) {
   212|        reasons.push('Files changed but tests failed — cannot become COMPLETED.');
   213|        return { ok: false, legal: true, reasons, from, to };
   214|      }
   215|      if (input.typecheckPassed === false) {
   216|        reasons.push('Typecheck was run and failed — cannot become COMPLETED.');
   217|        return { ok: false, legal: true, reasons, from, to };
   218|      }
   219|      if (!input.commitVerified) {
   220|        reasons.push('Commit was not created / verified — cannot become COMPLETED for a development task.');
   221|        return { ok: false, legal: true, reasons, from, to };
   222|      }
   223|      // Deploy + production health + feature verification are NOT required
   224|      // when deploy was not requested. Do not push any reason for them.
   225|    } else if (isReadOnly) {
   226|      // READ_ONLY: INSPECTION + FINDINGS = COMPLETED. No patch/commit/deploy.
   227|      if (input.filesChangedCount > 0) {
   228|        reasons.push('A read-only task cannot become COMPLETED with files changed.');
   229|        return { ok: false, legal: true, reasons, from, to };
   230|      }
   231|    } else if (isQaOnly) {
   232|      // QA_ONLY: TARGETED TESTS + RESULTS = COMPLETED. No patch/commit/deploy.
   233|      if (!input.testsRun) {
   234|        reasons.push('A QA-only task cannot become COMPLETED without targeted tests.');
   235|        return { ok: false, legal: true, reasons, from, to };
   236|      }
   237|    } else if (isDeployOnly) {
   238|      // DEPLOY_ONLY: VERIFIED COMMIT + DEPLOY + HEALTH = COMPLETED.
   239|      if (!input.commitVerified) {
   240|        reasons.push('A deploy-only task cannot become COMPLETED without a verified commit.');
   241|        return { ok: false, legal: true, reasons, from, to };
   242|      }
   243|      if (!input.deployId) {
   244|        reasons.push('A deploy-only task cannot become COMPLETED without a deployId.');
   245|        return { ok: false, legal: true, reasons, from, to };
   246|      }
   247|      if (!input.productionHealthOk) {
   248|        reasons.push('A deploy-only task cannot become COMPLETED without production health confirmed.');
   249|        return { ok: false, legal: true, reasons, from, to };
   250|      }
   251|    }
   252|    // FACTORY tasks: require commitVerified + filesChangedCount > 0 to be COMPLETED.
   253|    if (tt === 'FACTORY') {
   254|      if (input.filesChangedCount === 0) {
   255|        reasons.push('A factory task cannot become COMPLETED with no files created.');
   256|        return { ok: false, legal: true, reasons, from, to };
   257|      }
   258|      if (!input.commitVerified) {
   259|        reasons.push('A factory task cannot become COMPLETED without a verified commit.');
   260|        return { ok: false, legal: true, reasons, from, to };
   261|      }

