   166|/** Map granular stages to progress percentages. */
   167|const STAGE_PROGRESS: Record<IVXWorkerJobStage, number> = {
   168|  QUEUED: 0,
   169|  RUNNING: 10,
   170|  PATCHING: 25,
   171|  TESTING: 50,
   172|  COMMITTING: 65,
   173|  DEPLOYING: 80,
